      "content": "(function () {\n        var played = false;\n\n        function h1() {\n            return document.querySelector('#ss-p2 .ss-hero-title');\n        }\n\n        function clearInline(title) {\n            Array.prototype.slice.call(title.querySelectorAll('.ss-reveal-text, .ss-title-text')).forEach(function (text) {\n                text.classList.remove('is-final', 'codex-h1-square-text');\n                text.style.removeProperty('opacity');\n                text.style.removeProperty('visibility');\n                text.style.removeProperty('animation');\n                text.style.removeProperty('transform');\n                text.style.removeProperty('clip-path');\n                text.style.removeProperty('filter');\n            });\n            Array.prototype.slice.call(title.querySelectorAll('.ss-reveal-overlay')).forEach(function (overlay) {\n                overlay.style.removeProperty('display');\n                overlay.style.removeProperty('opacity');\n                overlay.style.removeProperty('transform');\n                overlay.style.removeProperty('transform-origin');\n                overlay.style.removeProperty('animation');\n            });\n        }\n\n        function visible(title) {\n            var rect = title.getBoundingClientRect();\n            return rect.top < window.innerHeight * 0.82 && rect.bottom > window.innerHeight * 0.04;\n        }\n\n        function prepare() {\n            var title = h1();\n            if (!title || played || visible(title)) return;\n            clearInline(title);\n            title.classList.remove('codex-p2-native-reveal-run', 'codex-p2-native-reveal-done', 'codex-h1-square-complete');\n            title.classList.add('codex-p2-same-band-ready');\n        }\n\n        function start() {\n            var title = h1();\n            if (!title || played || !visible(title)) return;\n            played = true;\n            clearInline(title);\n            title.classList.remove('codex-p2-same-band-ready', 'codex-p2-native-reveal-run', 'codex-p2-native-reveal-done', 'codex-h1-square-complete');\n            title.classList.add('codex-p2-same-band-run');\n            void title.offsetWidth;\n            window.setTimeout(function () {\n                title.classList.remove('codex-p2-same-band-run');\n                title.classList.add('codex-p2-same-band-done');\n                Array.prototype.slice.call(title.querySelectorAll('.ss-reveal-text, .ss-title-text')).forEach(function (text) {\n                    text.classList.add('is-final');\n                    text.style.setProperty('opacity', '1', 'important');\n                    text.style.setProperty('visibility', 'visible', 'important');\n                });\n            }, 1800);\n        }\n\n        function check() {\n            prepare();\n            start();\n        }\n\n        if (document.readyState === 'loading') {\n            document.addEventListener('DOMContentLoaded', check);\n        } else {\n            check();\n        }\n        window.addEventListener('load', function () {\n            window.setTimeout(check, 80);\n            window.setTimeout(check, 240);\n            window.setTimeout(check, 500);\n        });\n        window.addEventListener('scroll', function () {\n            window.setTimeout(check, 30);\n        }, { passive: true });\n        window.addEventListener('hashchange', function () {\n            window.setTimeout(check, 80);\n        });\n    })();"
